<?php require __DIR__.'/bootstrap.php';require_login();$pdo=db();$groups=['home'=>['title'=>'Home / Hero','description'=>'The first message visitors see when they open the website.','icon'=>'🏠','fields'=>['hero_eyebrow'=>['Hero eyebrow','input'],'hero_title'=>['Hero title','input'],'hero_text'=>['Hero description','textarea'],'intro_title'=>['Intro title','input'],'intro_text'=>['Intro text','textarea']]],'about'=>['title'=>'About Us','description'=>'Company story, mission and vision.','icon'=>'👷','fields'=>['about_title'=>['About title','input'],'about_text'=>['About paragraph 1','textarea'],'about_text_2'=>['About paragraph 2','textarea'],'mission'=>['Mission','textarea'],'vision'=>['Vision','textarea']]],'areas'=>['title'=>'Service Areas','description'=>'Coverage section headline and support text.','icon'=>'📍','fields'=>['areas_title'=>['Service Areas title','input'],'areas_text'=>['Service Areas text','textarea']]],'estimate'=>['title'=>'Free Estimate','description'=>'Text above the customer estimate form.','icon'=>'📝','fields'=>['estimate_title'=>['Estimate title','input'],'estimate_text'=>['Estimate text','textarea']]],'contact'=>['title'=>'Contact','description'=>'Main contact heading.','icon'=>'☎️','fields'=>['contact_title'=>['Contact title','input']]]];$fields=[];foreach($groups as $g)foreach($g['fields'] as $k=>$m)$fields[$k]=$m[0];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'draft';try{if($a==='draft'){$st=$pdo->prepare('INSERT INTO content_drafts(content_key,content_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE content_value=VALUES(content_value),updated_by=VALUES(updated_by)');foreach($fields as $k=>$label)$st->execute([$k,trim((string)($_POST[$k]??'')),(int)$_SESSION['cr_admin_id']]);log_activity('content_draft','Saved landing page draft');flash('success','Draft saved. The public website has not changed.');}elseif($a==='publish'){$live=site_content();$pdo->prepare('INSERT INTO content_versions(snapshot_json,note,created_by) VALUES(?,?,?)')->execute([json_encode($live,JSON_UNESCAPED_UNICODE),'Automatic version before publish',(int)$_SESSION['cr_admin_id']]);$draft=draft_content();if(!$draft)throw new RuntimeException('There is no draft to publish.');$st=$pdo->prepare('INSERT INTO site_content(content_key,content_value) VALUES(?,?) ON DUPLICATE KEY UPDATE content_value=VALUES(content_value)');foreach($draft as $k=>$v)$st->execute([$k,$v]);$pdo->exec('DELETE FROM content_drafts');log_activity('content_publish','Published landing page content');admin_notify('success','Website content published','The latest landing page draft is now live.','content.php');flash('success','Draft published to the public website.');}elseif($a==='discard'){$pdo->exec('DELETE FROM content_drafts');log_activity('content_draft_discard','Discarded landing page draft');flash('info','Draft discarded. Live content was preserved.');}elseif($a==='restore'){$id=(int)($_POST['version_id']??0);$st=$pdo->prepare('SELECT snapshot_json FROM content_versions WHERE id=?');$st->execute([$id]);$data=json_decode((string)$st->fetchColumn(),true);if(!is_array($data))throw new RuntimeException('Version could not be restored.');$up=$pdo->prepare('INSERT INTO content_drafts(content_key,content_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE content_value=VALUES(content_value),updated_by=VALUES(updated_by)');foreach($data as $k=>$v)$up->execute([$k,(string)$v,(int)$_SESSION['cr_admin_id']]);log_activity('content_restore','Restored content version to draft',['version_id'=>$id]);flash('success','Version restored as a draft.');}header('Location: content.php');exit;}catch(Throwable $e){flash('error',$e->getMessage());header('Location: content.php');exit;}}$live=site_content();$draft=draft_content();$editing=$draft?array_replace($live,$draft):$live;$versions=$pdo->query('SELECT id,note,created_at FROM content_versions ORDER BY id DESC LIMIT 10')->fetchAll();$pageTitle='Page Content';$active='content';require __DIR__.'/_header.php';?><div class="page-heading"><div><p class="eyebrow">PAGE CONTENT</p><h1>Edit landing page sections</h1><p class="muted">Save drafts, preview safely and publish only when ready.</p></div><div class="heading-actions"><a class="button secondary" href="../?preview=1&draft=1" target="_blank">Preview draft</a><a class="button ghost" href="../" target="_blank">View live site</a></div></div><div class="draft-status <?=$draft?'has-draft':'clean'?>"><span class="status-dot"></span><div><strong><?=$draft?'Unpublished changes':'Website is up to date'?></strong><small><?=$draft?'Edits are saved as a draft and are not public yet.':'There are no pending content changes.'?></small></div></div><div class="editor-layout"><form method="post" class="cms-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="draft"><div class="content-grid"><?php foreach($groups as $group):?><section class="content-card animate-in"><header><div class="panel-icon"><?=$group['icon']?></div><div><h2><?=h($group['title'])?></h2><p><?=h($group['description'])?></p></div></header><div class="field-stack"><?php foreach($group['fields'] as $k=>$m):?><label><?=h($m[0])?><?php if($m[1]==='textarea'):?><textarea name="<?=h($k)?>"><?=h($editing[$k]??'')?></textarea><?php else:?><input name="<?=h($k)?>" value="<?=h($editing[$k]??'')?>"><?php endif;?></label><?php endforeach;?></div></section><?php endforeach;?></div><div class="savebar"><button type="submit">Save draft</button><?php if($draft):?><button class="button publish" type="submit" name="action" value="publish">Publish changes</button><button class="button danger-lite" type="submit" name="action" value="discard" data-swal-confirm="Discard this draft?" data-swal-text="Your unpublished content changes will be removed.">Discard draft</button><?php endif;?></div></form><aside class="live-preview-panel"><div class="preview-panel-head"><div><strong>Live preview</strong><small>Shows the saved draft.</small></div><a href="../?preview=1&draft=1" target="_blank">Open ↗</a></div><iframe src="../?preview=1&draft=1" title="Draft website preview"></iframe></aside></div><section class="panel version-panel"><div class="section-heading"><div><p class="eyebrow">HISTORY</p><h2>Recent content versions</h2></div></div><?php if(!$versions):?><div class="empty-state"><strong>No versions yet</strong><p>A version is created before each publish.</p></div><?php else:?><div class="version-list"><?php foreach($versions as $v):?><article><div><strong><?=h($v['note']?:'Content version')?></strong><small><?=h($v['created_at'])?></small></div><form method="post" data-swal-confirm="Restore this version?" data-swal-text="It will be loaded as a draft."><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="restore"><input type="hidden" name="version_id" value="<?=$v['id']?>"><button class="button secondary small">Restore to draft</button></form></article><?php endforeach;?></div><?php endif;?></section><?php require __DIR__.'/_footer.php';